struct Point { x: i32, y: i32 }

impl Display for Point {
    fn to_string(self) -> String { return format("({}, {})", self.x, self.y); }
}

fn main() {
    let p = Point { x: 1, y: 2 };
    println(p);                // (1, 2)
    println("at {p:>10}");     // at     (1, 2)
    println("{p:?}");          // Point { x: 1, y: 2 }
}

import std.rand;

let mut rng = rand.Rng.from_seed(42);
println("{}", rng.below(6) + 1);       // a dice roll
println("{}", rng.between(10, 20));     // 10..=20
println("{:.3}", rng.float());          // 0.0 <= x < 1.0

import std.list;

fn by_value(a: *i32, b: *i32) -> i32 { return *a - *b; }

fn main() {
    let mut xs: list.List<i32> = list.List.new();
    xs.push(3);
    xs.push(1);
    xs.push(2);
    xs.sort_by(by_value);
    for i in 0..xs.len { println("{}", xs.get(i)); }   // 1 2 3
}

import std.stack;
let mut s: stack.Stack<i32> = stack.Stack.new();
s.push(1);
s.push(2);
println(s.pop() ?? -1);            // 2   (pop gives `T?`: empty when there is nothing left)
if s.peek() != null { println(*s.peek()); }     // peek gives a pointer to the top, or null

import std.queue;
let mut q: queue.Queue<str> = queue.Queue.new();
q.push("a");
q.push("b");
println(q.pop() ?? "empty");       // a   (pop gives `T?`)
println(q.len());                  // 1

modules.description:
The map owns its keys and values: it is destroyed automatically at the end of its scope, running each
value's destructor. Values with destructors are moved in (`set`) and out (`remove`) or borrowed (`get`);
`get_or` needs a copyable value type. The iteration order of `for_each` and `keys` is unspecified.

modules.example:
import std.map;
let mut ages: map.HashMap<i32> = map.HashMap.new();
ages.set("ann", 31);                     // keys are `str`; the map keeps its own copy
ages.set("bob", 27);
println(*ages.get("ann"));              // get gives a pointer to the value, or null
println(ages.get_or("zed", -1));         // a copy of the value, or the default
if ages.has("bob") { ages.remove("bob"); }

import std.tree;

struct Score { points: i32 }

impl tree.Ord for Score {
    fn cmp(self, other: *Score) -> i32 { return self.points - other.points; }
}

fn main() {
    let mut t: tree.Tree<Score> = tree.Tree.new();
    t.insert(Score { points: 30 });
    t.insert(Score { points: 10 });
    t.insert(Score { points: 20 });
    println("{}", t.min().points);   // 10
    println("{}", t.len());          // 3
}

import std.mem;

let mut a = 1;
let mut b = 2;
mem.swap(&a, &b);                 // a == 2, b == 1
println("{}", mem.max(a, b));     // 2
let mut xs = [5, 3, 9, 1];
mem.sort(xs[0..4]);               // 1 3 5 9

import std.own;

struct Node { value: i32, next: own.Own<Node> }

fn main() {
    let list = own.new(Node { value: 1, next: own.new(Node { value: 2, next: own.none() }) });
    println("{}", list.at().value);          // 1: `at` borrows the value
    let r = list.ref();                        // a checked handle that can outlive borrows
    println("{}", r.get().value);              // 1
    let shared = own.shared(5);
    let again = shared.clone();
    println("{}", again.count());               // 2: freed when the last owner goes
}
// at the end of main the whole list is freed, in order, right there

