import std.thread;

fn worker() { println("hello from a thread"); }

fn main() {
    let mut t = thread.spawn_fn(worker).catch(|e| { panic("spawn failed"); });
    t.join();
}

async fn square(n: i32) -> i32 { return n * n; }

fn main() {
    let a = square(6);          // starts right away, on its own thread
    let b = square(7);
    println("{}", await a + await b);   // 85
}
